local SettingRefBase = require('Game.Setting.SettingRefBase')

---@class WaveVo
local WaveVo = {}
WaveVo = Class("WaveVo", SettingRefBase)
local base = SettingRefBase
local ParseUtils = CS.ParseUtils
local parse_strings = parse_strings

---__int
function WaveVo:__init()
    self.id = nil
end

---FillVo
---@param row TableML.TableFileRow
function WaveVo:FillVo(row)
    base.FillVo(self,row)
    self.id = parse_number(row,"id", 0)
    
    self.initRoundNum = 0
    local ia = parse_string(row,"waveInitAction", '')
    self.hasInitAction = ia ~= "" and ia ~= "0"
    if self.hasInitAction then
        self.initActions = {}
        self:AddActions(self.initActions, ia)
        self.initRoundNum = #self.initActions
    end

    self.loopRoundNum = 0
    local la = parse_string(row,"waveLoopAction", '')
    self.hasloopAction = la ~= "" and la ~= "0"
    if self.hasloopAction then
        self.loopActions = {}
        self:AddActions(self.loopActions, la)
        self.loopRoundNum = #self.loopActions
    end

    --self.waveFront = parse_number(row,"wavefront", 0)
    --self.waveAfter = parse_number(row,"waveafter", 0)
    local tmp = parse_string(row,"wavefront", '')
    self.waveFront = string.isEmpty(tmp) and 0 or parse_strings(tmp)
    tmp = parse_string(row,"waveafter", '')
    self.waveAfter = string.isEmpty(tmp) and 0 or parse_strings(tmp)
    ----------------------------------
    --- boss详情要使用的字段
    self.wave      = parse_number(row, "wave", 0)
    self.wave1NpcId = parse_strings(parse_string(row, "wave1NpcId", ''))
    self.attribute = parse_strings(parse_string(row, "attribute", ''))
    self.wave1Level = parse_strings(parse_string(row, "wave1Level", ''))
    self.wave1NpcType = parse_strings(parse_string(row, "wave1NpcType", ''))

    self.skinId = parse_strings(parse_string(row, "skinId", ''))

    self.maxNum      = parse_number(row, "enemyNum", 0)
    self.halo        = parse_number(row, "halo", 0)

    self.scriptName = parse_string(row, "script", '')
    self.scriptData = parse_strings(parse_string(row, "scriptState", ''))
    self.winCondition = parse_number(row, "victory", 0)
    if self.winCondition == "" or self.winCondition == nil then
        self.winCondition = 0
    end
    self.loseCondition = parse_number(row, "defeat", 0)
    if self.loseCondition == "" or self.loseCondition == nil or self.loseCondition == 0 then
        self.loseCondition = -1
    end
    
    self.tips = parse_number(row, "tips")
    
    tmp = parse_string(row, "bubble")
    self.bubble = string.isEmpty(tmp) and 0 or parse_strings(tmp)

    local victory = parse_string(row, "victory", "")
    local strListV =  string.split2(victory, ";")
    self.victory = {}
    for i = 1, #strListV do
        table.insert(self.victory, strListV[i])
    end
    
    local defeat = parse_string(row, "defeat", "")
    local strListD =  string.split2(defeat, ";")
    self.defeat = {}
    for i = 1, #strListD do
        table.insert(self.defeat, strListD[i])
    end

    self.hpCount = parse_number(row, "hpCount")
    self.useRandomAction = parse_number(row, "behavior")
    self.sceneSkinName = parse_string(row, "SceneList", "")
end

function WaveVo:AddActions( actions, data )
    local rounds = string.slice(data, ',')
    for i,r in ipairs(rounds) do
        local l = string.slice(r, ';')
        local round = {}
        table.insert(actions, round)
        for j,a in ipairs(l) do
            local al = string.slice(a, '|')
            table.insert(round, {pos = tonumber(al[1]), skillPos = tonumber(al[2]), star = tonumber(al[3])})
        end
    end
end

function WaveVo:GetWaveScript(  )
    if Tools.isNullKey(self.scriptName) then
        return nil
    end
    return import('Game.BattleView.Script.Wave.' .. self.scriptName)
end

